SELECT userid, email, first_name, last_name, phone, addr1, addr2, city, state, zip, country, status
FROM account
WHERE userid = #{userId}

SELECT userid, language_preference, favourite_category, list_option, banner_option
FROM profile
WHERE userid = #{userId}

SELECT username, password_hash
FROM signon
WHERE username = #{username}

mapper.update:
UPDATE account
SET email = #{email}, first_name = #{firstName}, last_name = #{lastName}, phone = #{phone},
    addr1 = #{addr1}, addr2 = #{addr2}, city = #{city}, state = #{state}, zip = #{zip},
    country = #{country}
WHERE userid = #{userId}

UPDATE profile
SET language_preference = #{languagePreference}, favourite_category = #{favouriteCategoryId},
    list_option = #{listOption}, banner_option = #{bannerOption}
WHERE userid = #{userId}

UPDATE signon
SET password_hash = #{passwordHash}
WHERE username = #{username}
